"""RAG по проекту: документация — фрагменты по заголовкам, код Python — по функциям и классам;
векторы bge-m3, поиск по косинусу."""
import ast
import asyncio
import hashlib
import json
import re
import time

import numpy as np

from app import config, llm

MAX = 900  # знаков во фрагменте документации: короче промпт — быстрее отвечает локальная модель
MAX_CODE = 1500  # знаков во фрагменте кода: функция обычно помещается целиком
HEADING = re.compile(r"^(#{1,3})\s+(.+?)\s*$")


def files():
    """Файлы документации проекта по порядку: README, потом docs/."""
    found = []
    for pattern in config.DOCS:
        found += sorted(config.PROJECT_DIR.glob(pattern))
    return found


def _sections(text):
    """(заголовки над разделом, текст раздела); строки внутри ``` заголовками не считаются."""
    trail, body, in_code = [], [], False
    for line in text.splitlines():
        if line.startswith("```"):
            in_code = not in_code
        heading = None if in_code else HEADING.match(line)
        if heading:
            if "\n".join(body).strip():
                yield trail, "\n".join(body).strip()
            trail = trail[:len(heading.group(1)) - 1] + [heading.group(2)]
            body = []
        else:
            body.append(line)
    if "\n".join(body).strip():
        yield trail, "\n".join(body).strip()


def _blocks(body):
    """Абзацы; блок кода и таблица — целиком."""
    found, current, in_code = [], [], False
    for line in body.splitlines():
        if line.startswith("```"):
            in_code = not in_code
        if line.strip() or in_code:
            current.append(line)
        elif current:
            found.append("\n".join(current))
            current = []
    if current:
        found.append("\n".join(current))
    return found


def _pieces(block):
    """Блок длиннее MAX — по строкам; у таблицы в каждой части повторяется шапка."""
    if len(block) <= MAX:
        return [block]
    lines = block.splitlines()
    head = lines[:2] if lines[0].startswith("|") else []
    pieces, current = [], []
    for line in lines[len(head):]:
        if current and len("\n".join(head + current + [line])) > MAX:
            pieces.append("\n".join(head + current))
            current = []
        current.append(line)
    pieces.append("\n".join(head + current))
    return pieces


def split_docs(file, text):
    """Фрагменты Markdown: {"file", "title", "text", "kind"}; title — заголовки без названия документа."""
    for trail, body in _sections(text):
        title = " › ".join(trail[1:] or trail[:1])
        current = ""
        for block in _blocks(body):
            for piece in _pieces(block):
                # короткое начало (вступление к списку) не отрываем от продолжения
                if len(current) >= MAX // 3 and len(current) + len(piece) + 2 > MAX:
                    yield {"file": file, "title": title, "text": current, "kind": "docs"}
                    current = ""
                current = f"{current}\n\n{piece}" if current else piece
        if current:
            yield {"file": file, "title": title, "text": current, "kind": "docs"}


def _label(node):
    """Название верхнеуровневого узла Python для заголовка фрагмента."""
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
        return f"{node.name}()"
    if isinstance(node, ast.ClassDef):
        return f"class {node.name}"
    if isinstance(node, (ast.Import, ast.ImportFrom)):
        return "импорты"
    if isinstance(node, (ast.Assign, ast.AnnAssign, ast.AugAssign)):
        return ", ".join(ast.unparse(t) for t in getattr(node, "targets", None) or [node.target])
    if isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant) and isinstance(node.value.value, str):
        return "описание модуля"
    return "код модуля"


def split_code(file, text):
    """Фрагменты Python: функция или класс целиком, импорты и константы между ними — вместе; комментарий
    над узлом — с ним. У фрагмента — номера строк: на них ссылается ревью."""
    lines = text.splitlines()
    try:
        nodes = ast.parse(text).body
    except SyntaxError:
        nodes = []
    groups, start = [], 1  # [названия, первая строка, последняя строка, отдельный ли узел]
    for node in nodes:
        whole = isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))
        last = groups[-1] if groups else None
        if last and not whole and not last[3] and len("\n".join(lines[last[1] - 1:node.end_lineno])) <= MAX_CODE:
            last[0].append(_label(node))
            last[2] = node.end_lineno
        else:
            groups.append([[_label(node)], start, node.end_lineno, whole])
        start = node.end_lineno + 1
    if not groups and lines:
        groups.append([["код модуля"], 1, len(lines), False])
    for labels, first, end, _ in groups:
        while first < end and not lines[first - 1].strip():
            first += 1
        title = ", ".join(dict.fromkeys(labels))
        piece = first
        for n in range(first, end + 1):  # длинный фрагмент — по строкам
            if n > piece and len("\n".join(lines[piece - 1:n])) > MAX_CODE:
                yield {"file": file, "title": title, "text": "\n".join(lines[piece - 1:n - 1]),
                       "kind": "code", "lines": [piece, n - 1]}
                piece = n
        yield {"file": file, "title": title, "text": "\n".join(lines[piece - 1:end]), "kind": "code",
               "lines": [piece, end]}


def split(file, text):
    return split_code(file, text) if file.endswith(".py") else split_docs(file, text)


def source(chunk):
    """Заголовок фрагмента для промпта и ссылок: файл › раздел, у кода — ещё строки."""
    lines = f", строки {chunk['lines'][0]}–{chunk['lines'][1]}" if chunk.get("lines") else ""
    return f"{chunk['file']} › {chunk['title']}{lines}"


def _key(chunk):
    return hashlib.sha256(f"{config.EMBED_MODEL}|{chunk['file']}|{chunk['title']}|{chunk['text']}".encode()).hexdigest()


def _embedded(chunk):
    """Текст для вектора; у кода — с путём файла: запросы ревью тоже начинаются с пути."""
    if chunk["kind"] == "code":
        return f"{chunk['file']} › {chunk['title']}\n\n{chunk['text']}"
    return f"{chunk['title']}\n\n{chunk['text']}"


class Index:
    """Фрагменты и их векторы. Векторы кэшируются в data/<cache>.json: поменялись файлы —
    пересчитываются только новые фрагменты."""

    def __init__(self, cache):
        self.cache = config.DATA_DIR / f"{cache}.json"
        self.fingerprint, self.chunks, self.matrix, self.built = None, [], None, None

    async def build(self, texts):
        """texts — {путь: текст}."""
        fingerprint = hashlib.sha256(json.dumps(texts, sort_keys=True).encode()).hexdigest()
        if fingerprint == self.fingerprint:
            return
        started = time.perf_counter()
        chunks = [chunk for file, text in texts.items() for chunk in split(file, text)]
        cache = json.loads(self.cache.read_text(encoding="utf-8")) if self.cache.exists() else {}
        keys = [_key(chunk) for chunk in chunks]
        missing = [i for i, key in enumerate(keys) if key not in cache]
        if missing:
            vectors = await llm.embed([_embedded(chunks[i]) for i in missing])
            cache.update({keys[i]: vector for i, vector in zip(missing, vectors)})
            self.cache.parent.mkdir(parents=True, exist_ok=True)
            self.cache.write_text(json.dumps({key: cache[key] for key in keys}), encoding="utf-8")  # только живые
        matrix = None
        if keys:
            matrix = np.array([cache[key] for key in keys], dtype=np.float32)
            matrix /= np.linalg.norm(matrix, axis=1, keepdims=True)
        self.fingerprint, self.chunks, self.matrix = fingerprint, chunks, matrix
        self.built = {"embedded": len(missing), "seconds": round(time.perf_counter() - started, 2)}

    def info(self):
        return {"files": sorted({c["file"] for c in self.chunks}, key=lambda f: (f != "README.md", f)),
                "chunks": len(self.chunks), "model": config.EMBED_MODEL, "built": self.built}

    def nearest(self, vector, top, keep=lambda chunk: True):
        """Ближайшие по косинусу фрагменты, которые проходят фильтр keep, — с близостью. Можно передать
        несколько векторов запроса: у фрагмента берётся лучшая близость."""
        if self.matrix is None:
            return []
        queries = np.atleast_2d(np.array(vector, dtype=np.float32))
        scores = (self.matrix @ (queries / np.linalg.norm(queries, axis=1, keepdims=True)).T).max(axis=1)
        found = []
        for i in np.argsort(-scores):
            if len(found) == top:
                break
            if keep(self.chunks[i]):
                found.append({**self.chunks[i], "score": round(float(scores[i]), 3)})
        return found


docs = Index("embeddings")  # /help: README и docs/ из рабочей папки проекта
_lock = asyncio.Lock()  # сборка при старте и первый /help не считают векторы дважды


async def ensure_index():
    """Индекс документации актуален: поменяли файлы — пересчитываются векторы только новых фрагментов."""
    async with _lock:
        paths = files()
        if not paths:
            raise FileNotFoundError(f"В {config.PROJECT_DIR} нет README.md и docs/ — проверьте PROJECT_DIR")
        await docs.build({p.relative_to(config.PROJECT_DIR).as_posix(): p.read_text(encoding="utf-8") for p in paths})
        return docs.info()


def info():
    return docs.info()


async def search(question, top=config.TOP):
    """Ближайшие по смыслу фрагменты документации — по косинусу векторов bge-m3."""
    await ensure_index()
    return docs.nearest((await llm.embed([question]))[0], top)

"""Команда /help: контекст проекта по MCP → поиск по документации → ответ локальной модели."""
import json
import time

from mcp import Client

from app import config, llm, rag

SYSTEM = """Ты — ассистент разработчика проекта ml-student-dropout. Отвечай по-русски, коротко: 2–5 предложений или список.
Опирайся только на «Контекст проекта» и «Фрагменты документации».
После утверждения из документации ставь ссылку на фрагмент — его заголовок в квадратных скобках, например [docs/model.md › Причины риска].
Про ветку, изменения и файлы отвечай по контексту проекта.
Если ответа нет ни там, ни там — так и скажи: «В документации этого нет».
Команды, пути, имена файлов и полей пиши в `обратных кавычках`."""

OVERVIEW = "Что это за проект, как он устроен и как его запустить?"
CHANGES = ("измен", "правк", "поменя", "diff", "дифф")  # вопрос про правки — нужен ещё и diff
GROUPS = {"изменён": "изменены", "новый": "новые", "удалён": "удалены", "добавлен": "добавлены",
          "переименован": "переименованы", "конфликт": "с конфликтом"}


def parse(text):
    """'/help вопрос' → вопрос; просто '/help' — вопрос о проекте в целом; без /help — None."""
    text = text.strip()
    if text != "/help" and not text.startswith("/help "):
        return None
    return text[len("/help"):].strip() or OVERVIEW


def server_info(client):
    return {"name": client.server_info.name if client.server_info else "?",
            "version": client.server_info.version if client.server_info else "",
            "protocol": client.protocol_version}


async def call(client, calls, name, args):
    """Вызов инструмента MCP: запись с временем и результатом — в calls; вернёт результат или None при ошибке."""
    started = time.perf_counter()
    result = await client.call_tool(name, args)
    text = "".join(getattr(part, "text", "") for part in result.content)
    calls.append({"tool": name, "args": args, "ok": not result.is_error,
                  "result": result.structured_content if result.structured_content is not None else text,
                  "ms": round((time.perf_counter() - started) * 1000)})
    return calls[-1]["result"] if calls[-1]["ok"] else None


async def call_tools(plan):
    """Одна сессия MCP: вызовы инструментов по очереди с временем и результатом."""
    calls = []
    async with Client(config.MCP_URL, read_timeout_seconds=30) as client:
        server = server_info(client)
        for name, args in plan:
            await call(client, calls, name, args)
    return server, calls


def context_text(calls):
    """Результаты MCP — коротким текстом для модели."""
    got = {c["tool"]: c["result"] for c in calls if c["ok"]}
    lines = [f"Проект: {config.PROJECT_DIR.name}"]
    if branch := got.get("git_branch"):
        lines.append(f"Текущая ветка: {branch['branch']}; ветки: {', '.join(branch['branches'])}; "
                     f"последний коммит: {branch['last_commit']}")
    if status := got.get("git_status"):
        groups = {}
        for c in status["changed"]:
            groups.setdefault(GROUPS.get(c["status"], c["status"]), []).append(c["path"])
        parts = [f"{name} ({len(paths)}): {', '.join(paths[:12])}{' …' if len(paths) > 12 else ''}"
                 for name, paths in groups.items()]
        lines.append("Незакоммиченных изменений нет" if status["clean"]
                     else f"Незакоммиченные изменения — {status['count']} файлов. " + "; ".join(parts))
    if files := got.get("list_files"):
        lines.append(f"Файлы проекта ({files['count']}): {', '.join(files['files'])}")
    if diff := got.get("git_diff"):
        lines.append(f"Diff ({diff['lines']} строк{', начало' if diff['truncated'] else ''}):\n{diff['diff'] or '(пусто)'}")
    return "\n".join(lines)


def messages(question, context, hits):
    # Неизменная часть — системный промпт и контекст проекта — идёт первой: Ollama кэширует начало промпта
    fragments = "\n\n".join(f"[{h['file']} › {h['title']}]\n{h['text']}" for h in hits)
    user = (f"Контекст проекта (git, получен через MCP):\n{context}\n\nВопрос: {question}\n\n"
            f"Фрагменты документации:\n\n{fragments}\n\nВопрос: {question}")
    return [{"role": "system", "content": SYSTEM}, {"role": "user", "content": user}]


async def answer(question):
    """Шаги ответа событиями: mcp → sources → prompt → text… → done; ошибка — error с номером шага."""
    yield {"type": "question", "question": question}

    step = "mcp"
    try:
        started = time.perf_counter()
        plan = [("git_branch", {}), ("git_status", {}), ("list_files", {})]
        if any(word in question.lower() for word in CHANGES):
            plan.append(("git_diff", {}))
        server, calls = await call_tools(plan)
        context = context_text(calls)
        yield {"type": "mcp", "server": server, "calls": calls, "seconds": round(time.perf_counter() - started, 2)}

        step = "sources"
        started = time.perf_counter()
        hits = await rag.search(question)
        yield {"type": "sources", "hits": hits, "index": rag.info(), "seconds": round(time.perf_counter() - started, 2)}

        step = "answer"
        prompt = messages(question, context, hits)
        yield {"type": "prompt", "messages": prompt, "chars": sum(len(m["content"]) for m in prompt)}
        async for event in llm.chat(prompt):
            yield event
    except llm.LLMError as exc:
        yield {"type": "error", "step": step, "message": str(exc)}
    except Exception as exc:  # MCP, git, файлы — показываем словами, а не падением
        yield {"type": "error", "step": step, "message": reason(exc)}


def reason(exc):
    """Причина ошибки; клиент MCP бросает ExceptionGroup — достаём первую настоящую."""
    while isinstance(exc, BaseExceptionGroup) and exc.exceptions:
        exc = exc.exceptions[0]
    return getattr(exc, "message", None) or str(exc) or type(exc).__name__


async def project():
    """Шапка страницы: проект и ветка — тоже через MCP."""
    try:
        _, calls = await call_tools([("git_branch", {})])
        return {"name": config.PROJECT_DIR.name, "branch": calls[0]["result"]["branch"] if calls[0]["ok"] else None}
    except Exception as exc:
        return {"name": config.PROJECT_DIR.name, "branch": None, "error": reason(exc)}


def dumps(event):
    return json.dumps(event, ensure_ascii=False) + "\n"

"""Ollama по HTTP: векторы для поиска (bge-m3) и ответ потоком (qwen3.5:4b)."""
import json

import httpx2

from app import config


class LLMError(Exception):
    """Ошибка по-человечески: что случилось и что сделать."""


# Под ответ по фрагментам: факты, а не творчество (подобрано на неделе 6, день 29)
OPTIONS = {"temperature": 0.1, "top_p": 0.8, "presence_penalty": 0, "num_predict": 512, "num_ctx": 4096}
NOT_RUNNING = "Ollama не запущен — откройте его из меню «Пуск»"


def _client(read=None):
    return httpx2.AsyncClient(base_url=config.OLLAMA_URL, trust_env=False, timeout=httpx2.Timeout(10, read=read))


def _missing(model):
    return LLMError(f"Модели {model} нет — скачайте: ollama pull {model}")


async def status():
    """Запущен ли Ollama и скачаны ли обе модели."""
    try:
        async with _client(5) as client:
            version = (await client.get("/api/version")).json()["version"]
            names = {m["name"] for m in (await client.get("/api/tags")).json()["models"]}
    except httpx2.HTTPError:
        return {"running": False}
    return {"running": True, "version": version,
            "models": {model: model in names or f"{model}:latest" in names for model in (config.MODEL, config.EMBED_MODEL)}}


async def load():
    """Загрузить модель в память заранее — иначе первый ответ ждёт ещё 5–8 с."""
    try:
        async with _client(120) as client:
            await client.post("/api/generate", json={"model": config.MODEL})
    except httpx2.ConnectError:
        raise LLMError(NOT_RUNNING)


async def embed(texts):
    """Векторы bge-m3 для списка текстов."""
    try:
        async with _client(600) as client:
            response = await client.post("/api/embed", json={"model": config.EMBED_MODEL, "input": texts})
    except httpx2.ConnectError:
        raise LLMError(NOT_RUNNING)
    if response.status_code == 404:
        raise _missing(config.EMBED_MODEL)
    response.raise_for_status()
    return response.json()["embeddings"]


async def chat(messages, options=None, schema=None, tools=None):
    """Ответ потоком: {"type": "text"} кусочками, вызовы инструментов — {"type": "tool_calls"}, в конце
    {"type": "done"} со счётчиками. options дополняют OPTIONS; schema — JSON Schema, от которой Ollama не даст
    модели отойти; tools — инструменты, которые модель может вызвать сама."""
    body = {"model": config.MODEL, "messages": messages, "stream": True, "think": False,
            "options": {**OPTIONS, **(options or {})}}
    if schema:
        body["format"] = schema
    if tools:
        body["tools"] = tools
    try:
        async with _client() as client, client.stream("POST", "/api/chat", json=body) as response:
            if response.status_code == 404:
                raise _missing(config.MODEL)
            if response.status_code != 200:
                raise LLMError(f"Ollama ответил {response.status_code}: {(await response.aread()).decode()[:200]}")
            async for line in response.aiter_lines():
                if not line:
                    continue
                part = json.loads(line)
                if part.get("error"):
                    raise LLMError(part["error"])
                if text := part.get("message", {}).get("content"):
                    yield {"type": "text", "text": text}
                if calls := part.get("message", {}).get("tool_calls"):
                    yield {"type": "tool_calls", "calls": calls}
                if part.get("done"):
                    yield {"type": "done", **_counters(part)}
    except httpx2.ConnectError:
        raise LLMError(NOT_RUNNING)


def _counters(part):
    sec = lambda key: part.get(key, 0) / 1e9  # Ollama отдаёт наносекунды
    tokens = part.get("eval_count", 0)
    return {
        "tokens": tokens,
        "speed": round(tokens / sec("eval_duration"), 1) if part.get("eval_duration") else 0,
        "prompt": part.get("prompt_eval_count", 0),
        "reading": round(sec("prompt_eval_duration"), 2),
        "writing": round(sec("eval_duration"), 2),
        "load": round(sec("load_duration"), 2),
        "seconds": round(sec("total_duration"), 2),
    }

"""MCP-сервер files: чтение, поиск, правка и создание файлов проекта. Правки копятся в черновике: чтение и
поиск их уже видят, а на диск их записывает apply_draft — после того как человек посмотрел diff."""
import difflib
import re
from typing import Annotated, Any

from mcp.server.mcpserver import MCPServer
from mcp.server.mcpserver.exceptions import ToolError
from pydantic import Field

from app import config
from app.git_mcp import git

server = MCPServer(
    name="files",
    version="1.0.0",
    instructions="Файлы проекта, с которым работает ассистент: список, чтение с номерами строк, поиск по всем "
                 "файлам, правка и создание. Правки копятся в черновике и видны при чтении и поиске; на диск их "
                 "записывает apply_draft, отменяет discard_draft.",
)

READ_LINES = 80  # строк за один read_file: файл целиком раздувает промпт локальной модели
MATCHES = 60  # совпадений поиска в ответе
NUMBERED = re.compile(r"^\d+\| ?", re.M)  # так read_file нумерует строки
FilePath = Annotated[str, Field(description="Файл внутри проекта, например docs/api.md")]

draft = {}  # путь → текст файла с правками; на диске пока прежний


def _rel(path):
    """Путь относительно проекта; за пределы проекта и в .git — нельзя."""
    full = (config.PROJECT_DIR / path.strip().replace("\\", "/").lstrip("/")).resolve()
    if not full.is_relative_to(config.PROJECT_DIR) or full == config.PROJECT_DIR:
        raise ToolError(f"{path}: путь вне проекта")
    rel = full.relative_to(config.PROJECT_DIR).as_posix()
    if rel.split("/")[0] == ".git":
        raise ToolError(f"{path}: папка .git недоступна")
    return rel


def _disk(rel):
    """Текст файла на диске, переводы строк — \\n; None — файла нет."""
    file = config.PROJECT_DIR / rel
    if not file.is_file():
        return None
    try:
        return file.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        raise ToolError(f"{rel}: не текстовый файл")


def _text(rel):
    text = draft[rel] if rel in draft else _disk(rel)
    if text is None:
        raise ToolError(f"{rel}: такого файла нет — посмотрите list_files или search")
    return text


def _files(path=""):
    """Файлы проекта без игнорируемых git и новые файлы черновика."""
    prefix = _rel(path) if path.strip(" ./") else ""  # «.» и «/» — весь проект
    found = set(git("ls-files", "--cached", "--others", "--exclude-standard", "--", prefix or ".").splitlines())
    found |= {rel for rel in draft if not prefix or rel == prefix or rel.startswith(prefix + "/")}
    return sorted(found)


def _plain(text):
    """Модель иногда копирует строки из read_file вместе с номерами — номера убираем."""
    text = text.replace("\r\n", "\n")
    if all(NUMBERED.match(line) for line in text.split("\n") if line):
        text = NUMBERED.sub("", text)
    return text


def _find(text, old):
    """Вхождения old: точные, а если их нет — без учёта пробелов и переводов строк: модель склеивает строки
    абзаца в одну."""
    if text.count(old):
        return [old] * text.count(old)
    return [m.group(0) for m in re.finditer(r"\s+".join(map(re.escape, old.split())), text)]


def _respace(found, new):
    """Переносы строк в замене — там же, где в файле, если слов столько же."""
    gaps, words = re.findall(r"\s+", found), new.split()
    if len(words) != len(gaps) + 1:
        return new.strip()
    return words[0] + "".join(gap + word for gap, word in zip(gaps, words[1:]))


def _diff(rel, old, new, context=3):
    return "\n".join(difflib.unified_diff(old.splitlines() if old is not None else [], new.splitlines(),
                                          "/dev/null" if old is None else f"a/{rel}", f"b/{rel}",
                                          n=context, lineterm=""))


def _counts(diff):
    lines = diff.splitlines()[2:]  # без заголовков --- и +++
    return {"added": sum(line.startswith("+") for line in lines),
            "removed": sum(line.startswith("-") for line in lines)}


@server.tool()
def list_files(
    path: Annotated[str, Field(description="Папка внутри проекта, например docs; пусто — весь проект")] = "",
) -> dict[str, Any]:
    """Файлы проекта: отслеживаемые git и новые, без игнорируемых (.venv, data, models), вместе с файлами,
    созданными в черновике."""
    files = _files(path)
    return {"path": path or ".", "count": len(files), "files": files}


@server.tool()
def read_file(
    path: FilePath,
    start: Annotated[int, Field(ge=1, description="Первая строка")] = 1,
    end: Annotated[int, Field(ge=0, description="Последняя строка; 0 — следующие 80 строк")] = 0,
) -> dict[str, Any]:
    """Текст файла с номерами строк, вместе с правками черновика. За раз — до 80 строк: читайте кусок
    вокруг строк, найденных search."""
    rel = _rel(path)
    lines = _text(rel).splitlines()
    if lines and start > len(lines):
        raise ToolError(f"В {rel} всего {len(lines)} строк")
    end = min(len(lines), end or start + READ_LINES - 1, start + READ_LINES - 1)
    return {"path": rel, "lines": len(lines), "from": start, "to": end, "draft": rel in draft,
            "text": "\n".join(f"{n}| {lines[n - 1]}" for n in range(start, end + 1))}


@server.tool()
def search(
    query: Annotated[str, Field(description="Что искать, без учёта регистра; несколько вариантов — через |")],
    path: Annotated[str, Field(description="Папка или файл; пусто — весь проект")] = "",
) -> dict[str, Any]:
    """Поиск по всем текстовым файлам проекта, вместе с правками черновика: файл, номер строки и сама строка."""
    words = [word.strip().lower() for word in query.split("|") if word.strip()]
    if not words:
        raise ToolError("Пустой запрос")
    matches, files = [], set()
    for rel in _files(path):
        try:
            text = _text(rel)
        except ToolError:  # двоичный файл
            continue
        for n, line in enumerate(text.splitlines(), 1):
            if any(word in line.lower() for word in words):
                matches.append(f"{rel}:{n}: {line.strip()[:200]}")
                files.add(rel)
    return {"query": query, "count": len(matches), "files": len(files), "truncated": len(matches) > MATCHES,
            "matches": matches[:MATCHES]}


@server.tool()
def edit_file(
    path: FilePath,
    old: Annotated[str, Field(description="Точный текст из файла, который заменить; встречается в файле один раз")],
    new: Annotated[str, Field(description="Текст на его место")],
) -> dict[str, Any]:
    """Заменить кусок файла. Правка идёт в черновик, на диск её записывает пользователь."""
    rel = _rel(path)
    text = _text(rel)
    old, new = _plain(old), _plain(new)
    found = _find(text, old) if old.strip() else []
    if not found:
        raise ToolError(f"В {rel} нет такого текста: прочитайте нужные строки read_file и скопируйте их точно, "
                        "без номеров строк")
    if len(found) > 1:
        raise ToolError(f"Этот текст встречается в {rel} {len(found)} раз(а) — добавьте соседние строки, "
                        "чтобы он был один")
    if found[0] != old:
        new = _respace(found[0], new)
    if found[0] == new:
        raise ToolError("new совпадает с old — правка ничего не меняет")
    changed = text.replace(found[0], new, 1)
    draft[rel] = changed
    diff = _diff(rel, text, changed, context=1)
    return {"path": rel, **_counts(diff), "diff": diff}


@server.tool()
def write_file(
    path: Annotated[str, Field(description="Путь нового файла, например CHANGELOG.md")],
    content: Annotated[str, Field(description="Полный текст файла")],
) -> dict[str, Any]:
    """Создать новый файл — в черновике. Существующий файл меняйте через edit_file."""
    rel = _rel(path)
    if rel in draft or (config.PROJECT_DIR / rel).exists():
        raise ToolError(f"{rel} уже есть — меняйте его через edit_file")
    draft[rel] = content.replace("\r\n", "\n").rstrip("\n") + "\n"
    return {"path": rel, "lines": draft[rel].count("\n"), "created": True}


@server.tool()
def draft_diff() -> dict[str, Any]:
    """Все правки черновика: unified diff каждого файла против диска и сколько строк добавлено и удалено."""
    files = []
    for rel in sorted(draft):
        old = _disk(rel)
        if draft[rel] == old:
            continue
        diff = _diff(rel, old, draft[rel])
        files.append({"path": rel, "status": "новый" if old is None else "изменён", **_counts(diff), "diff": diff})
    return {"files": files, "added": sum(f["added"] for f in files), "removed": sum(f["removed"] for f in files)}


@server.tool()
def apply_draft() -> dict[str, Any]:
    """Записать правки черновика в файлы проекта и очистить черновик."""
    written = []
    for rel, text in sorted(draft.items()):
        file = config.PROJECT_DIR / rel
        # переводы строк — как были у файла: с core.autocrlf в рабочей папке бывают и CRLF, и LF
        newline = "\r\n" if file.is_file() and b"\r\n" in file.read_bytes() else "\n"
        file.parent.mkdir(parents=True, exist_ok=True)
        file.write_text(text, encoding="utf-8", newline=newline)
        written.append(rel)
    draft.clear()
    return {"written": written, "count": len(written)}


@server.tool()
def discard_draft() -> dict[str, Any]:
    """Отменить все правки черновика."""
    count = len(draft)
    draft.clear()
    return {"discarded": count}

"""MCP-сервер CRM поддержки: клиенты сервиса и их обращения из JSON-файла. Только чтение."""
import json
from typing import Annotated, Any

from mcp.server.mcpserver import MCPServer
from mcp.server.mcpserver.exceptions import ToolError
from pydantic import Field

from app import config

server = MCPServer(
    name="crm",
    version="1.0.0",
    instructions="CRM поддержки сервиса «Риск отчисления студентов»: клиенты — сотрудники вузов — и их обращения "
                 "с техническими данными: запрос, ответ сервиса, лог. Инструменты только читают, ничего не меняют.",
)

CLOSED = {"решён"}


def load():
    # файл читается на каждый вызов: правки CRM видны без перезапуска
    return json.loads(config.CRM_FILE.read_text(encoding="utf-8"))


def find(items, item_id, what):
    for item in items:
        if item["id"] == item_id.strip().upper():
            return item
    raise ToolError(f"{what} {item_id} нет в CRM")


@server.tool()
def list_tickets(
    include_closed: Annotated[bool, Field(description="Показать и решённые обращения")] = False,
) -> dict[str, Any]:
    """Очередь обращений, новые сверху: номер, тема, сообщение клиента, статус, приоритет, дата и клиент."""
    crm = load()
    users = {u["id"]: u for u in crm["users"]}
    tickets = [{**{k: t[k] for k in ("id", "subject", "message", "status", "priority", "created")},
                "user": {k: users[t["user_id"]][k] for k in ("id", "name", "org")}}
               for t in crm["tickets"] if include_closed or t["status"] not in CLOSED]
    tickets.sort(key=lambda t: t["created"], reverse=True)
    return {"count": len(tickets), "tickets": tickets}


@server.tool()
def get_ticket(ticket_id: Annotated[str, Field(description="Номер обращения, например T-1041")]) -> dict[str, Any]:
    """Обращение целиком: сообщение клиента, статус, приоритет и технические данные — запрос, ответ сервиса, лог."""
    return find(load()["tickets"], ticket_id, "Обращения")


@server.tool()
def get_user(user_id: Annotated[str, Field(description="Номер клиента, например U-01")]) -> dict[str, Any]:
    """Клиент: вуз, роль, как работает с сервисом, заметки поддержки и все его обращения с решениями."""
    crm = load()
    user = find(crm["users"], user_id, "Клиента")
    tickets = [{k: t[k] for k in ("id", "subject", "status", "created", "resolution") if k in t}
               for t in crm["tickets"] if t["user_id"] == user["id"]]
    return {**user, "tickets": tickets}

"""MCP-сервер git: ветка, изменения, файлы и diff проекта, история, изменения pull request. Только чтение."""
import subprocess
from typing import Annotated, Any

from mcp.server.mcpserver import MCPServer
from mcp.server.mcpserver.exceptions import ToolError
from pydantic import Field

from app import config

server = MCPServer(
    name="git",
    version="1.2.0",
    instructions="Git-репозиторий проекта, о котором отвечает ассистент: текущая ветка, незакоммиченные "
                 "изменения, список файлов, diff, история коммитов, файлы любого коммита и изменения pull request "
                 "между двумя ветками. Инструменты только читают, ничего не меняют.",
)

STATUS = {"M": "изменён", "A": "добавлен", "D": "удалён", "R": "переименован", "?": "новый", "U": "конфликт"}
Ref = Annotated[str, Field(description="Ветка или коммит, например main")]
# diff PR разбирается кодом: один формат при любых настройках git пользователя (цвет, префиксы, внешний diff)
PLAIN = ["--no-color", "--no-ext-diff", "--no-renames"]


def git(*args):
    # quotepath=false — пути не по-латински приходят как есть, а не восьмеричными кодами
    done = subprocess.run(["git", "-c", "core.quotepath=false", "-C", str(config.PROJECT_DIR), *args],
                          capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=15)
    if done.returncode != 0:
        # ToolError доходит до клиента своим текстом; любое другое исключение SDK прячет за общей фразой
        raise ToolError(done.stderr.strip() or f"git {' '.join(args)} завершился с кодом {done.returncode}")
    return done.stdout


@server.tool()
def git_branch() -> dict[str, Any]:
    """Текущая ветка, все локальные ветки и последний коммит."""
    return {
        "branch": git("branch", "--show-current").strip() or "(detached HEAD)",
        "branches": git("branch", "--format=%(refname:short)").split(),
        # точная дата, а не «5 минут назад»: начало промпта не меняется, и Ollama берёт его из кэша
        "last_commit": git("log", "-1", "--format=%h %s · %cd", "--date=format:%d.%m.%Y %H:%M").strip(),
    }


@server.tool()
def git_status() -> dict[str, Any]:
    """Незакоммиченные изменения: какие файлы изменены, добавлены, удалены или новые."""
    changed = []
    for line in git("status", "--porcelain=v1", "--untracked-files=all").splitlines():
        code = line[:2].strip()
        changed.append({"path": line[3:].strip('"'), "status": STATUS.get(code[:1], code)})
    return {"clean": not changed, "count": len(changed), "changed": changed}


@server.tool()
def list_files(
    path: Annotated[str, Field(description="Папка внутри проекта, например src/ml; пусто — весь проект")] = "",
    ref: Annotated[str, Field(description="Ветка или коммит; пусто — рабочая папка с новыми файлами")] = "",
) -> dict[str, Any]:
    """Файлы проекта — отслеживаемые git и новые, без игнорируемых (.venv, data, models); или файлы коммита."""
    if ref:
        found = git("ls-tree", "-r", "--name-only", ref, "--", path or ".").splitlines()
    else:
        found = git("ls-files", "--cached", "--others", "--exclude-standard", "--", path or ".").splitlines()
    return {"path": path or ".", "ref": ref, "count": len(found), "files": found}


@server.tool()
def read_file(
    path: Annotated[str, Field(description="Файл внутри проекта, например src/ml/model.py")],
    ref: Ref = "HEAD",
) -> dict[str, Any]:
    """Текст файла в указанном коммите или ветке."""
    return {"path": path, "ref": ref, "text": git("show", f"{ref}:{path}")}


@server.tool()
def git_diff(
    path: Annotated[str, Field(description="Файл внутри проекта; пусто — все изменения")] = "",
    max_lines: Annotated[int, Field(ge=10, le=400, description="Сколько строк diff вернуть")] = 80,
) -> dict[str, Any]:
    """Незакоммиченные правки отслеживаемых файлов (git diff HEAD): что именно поменялось."""
    lines = git("diff", "HEAD", "--", path or ".").splitlines()
    return {"path": path or ".", "lines": len(lines), "truncated": len(lines) > max_lines,
            "diff": "\n".join(lines[:max_lines])}


@server.tool()
def git_log(
    n: Annotated[int, Field(ge=1, le=50, description="Сколько последних коммитов")] = 20,
    path: Annotated[str, Field(description="Только коммиты, которые меняли этот файл или папку; пусто — все")] = "",
    oldest_first: Annotated[bool, Field(description="Сначала старые коммиты — история по порядку")] = False,
) -> dict[str, Any]:
    """История текущей ветки без merge-коммитов, новые сверху: дата, хеш, сообщение, изменённые файлы и
    сколько строк добавлено и удалено."""
    commits = []
    out = git("log", f"-{n}", "--no-merges", *(["--reverse"] if oldest_first else []), *PLAIN, "--numstat",
              "--date=format:%d.%m.%Y", "--format=%x1e%h%x1f%ad%x1f%s", "--", path or ".")
    for record in out.split("\x1e")[1:]:
        head, *lines = record.strip("\n").split("\n")
        sha, date, subject = head.split("\x1f")
        stats = [line.split("\t", 2) for line in lines if line]
        commits.append({"date": date, "hash": sha, "subject": subject, "files": [file for _, _, file in stats],
                        # «-» вместо числа — двоичный файл
                        "added": sum(int(a) for a, _, _ in stats if a != "-"),
                        "deleted": sum(int(d) for _, d, _ in stats if d != "-")})
    return {"count": len(commits), "commits": commits}


@server.tool()
def pr_files(base: Ref, head: Ref) -> dict[str, Any]:
    """Изменённые файлы pull request — что сделано в head с момента ответвления от base: статус файла и
    сколько строк добавлено и удалено. Переименование показывается как удаление и добавление."""
    changes = f"{base}...{head}"
    counts = {}
    for line in git("diff", "--numstat", *PLAIN, changes).splitlines():
        added, deleted, path = line.split("\t", 2)
        counts[path] = (int(added), int(deleted)) if added != "-" else (0, 0)  # «-» — двоичный файл
    files = []
    for line in git("diff", "--name-status", *PLAIN, changes).splitlines():
        code, path = line.split("\t", 1)
        added, deleted = counts.get(path, (0, 0))
        files.append({"path": path, "status": STATUS.get(code[:1], code), "added": added, "deleted": deleted})
    return {
        "base": base, "head": head,
        "merge_base": git("merge-base", base, head).strip(),
        "head_sha": git("rev-parse", head).strip(),
        "files": files,
        "added": sum(f["added"] for f in files),
        "deleted": sum(f["deleted"] for f in files),
    }


@server.tool()
def pr_diff(
    base: Ref,
    head: Ref,
    path: Annotated[str, Field(description="Файл внутри проекта; пусто — все файлы")] = "",
    max_lines: Annotated[int, Field(ge=10, le=5000, description="Сколько строк diff вернуть")] = 2000,
) -> dict[str, Any]:
    """Diff pull request (git diff base...head): изменения head с момента ответвления от base,
    по 5 строк контекста вокруг правок."""
    lines = git("diff", "-U5", *PLAIN, "--src-prefix=a/", "--dst-prefix=b/", f"{base}...{head}", "--",
                path or ".").splitlines()
    return {"path": path or ".", "lines": len(lines), "truncated": len(lines) > max_lines,
            "diff": "\n".join(lines[:max_lines])}
